ALTER TABLE ship_pins ADD COLUMN tag TEXT CHECK (typeof(tag) IN ('text','null'));
ALTER TABLE ship_pins ADD COLUMN ruff TEXT CHECK (typeof(ruff) IN ('text','null'));
ALTER TABLE ship_pins ADD COLUMN sweep TEXT CHECK (typeof(sweep) IN ('text','null'));
ALTER TABLE ship_pins ADD COLUMN rest TEXT CHECK (rest IS NULL OR (json_valid(rest) AND NOT coalesce(json_type(rest, '$.tag') IN ('text'), 0) AND NOT coalesce(json_type(rest, '$.ruff') IN ('text'), 0) AND NOT coalesce(json_type(rest, '$.sweep') IN ('text'), 0)));
CREATE TABLE ship_pin_repos(result TEXT NOT NULL, repo TEXT NOT NULL, status TEXT, said TEXT, at REAL NOT NULL, PRIMARY KEY (result, repo)) STRICT, WITHOUT ROWID;
CREATE INDEX ship_pin_repos_at ON ship_pin_repos(at);
CREATE TRIGGER ship_pins_fill AFTER INSERT ON ship_pins WHEN NEW.rest IS NULL AND json_valid(NEW.body) BEGIN
  DELETE FROM ship_pin_repos WHERE result = NEW.result;
  UPDATE ship_pins SET tag = CASE WHEN json_type(NEW.body, '$.tag') IN ('text') THEN NEW.body ->> '$.tag' END, ruff = CASE WHEN json_type(NEW.body, '$.ruff') IN ('text') THEN NEW.body ->> '$.ruff' END, sweep = CASE WHEN json_type(NEW.body, '$.sweep') IN ('text') THEN NEW.body ->> '$.sweep' END, rest = json_remove(NEW.body, CASE WHEN json_type(NEW.body, '$.tag') IN ('text') OR json_type(NEW.body, '$.tag') = 'null' THEN '$.tag' ELSE '$."__goh_noop__"' END, CASE WHEN json_type(NEW.body, '$.ruff') IN ('text') OR json_type(NEW.body, '$.ruff') = 'null' THEN '$.ruff' ELSE '$."__goh_noop__"' END, CASE WHEN json_type(NEW.body, '$.sweep') IN ('text') OR json_type(NEW.body, '$.sweep') = 'null' THEN '$.sweep' ELSE '$."__goh_noop__"' END, CASE WHEN (json_type(NEW.body, '$.repos') = 'object' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.repos') e WHERE e.type <> 'object' OR EXISTS (SELECT 1 FROM json_each(e.value) k WHERE k.type <> 'null' AND NOT ((k.key = 'status' AND k.type IN ('text')) OR (k.key = 'said' AND k.type IN ('text')))))) OR json_type(NEW.body, '$.repos') = 'null' THEN '$.repos' ELSE '$."__goh_noop__"' END, '$.schema') WHERE result = NEW.result;
  INSERT INTO ship_pin_repos SELECT NEW.result, e.key, e.value ->> '$.status', e.value ->> '$.said', NEW.at FROM json_each(NEW.body, '$.repos') e WHERE (json_type(NEW.body, '$.repos') = 'object' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.repos') e WHERE e.type <> 'object' OR EXISTS (SELECT 1 FROM json_each(e.value) k WHERE k.type <> 'null' AND NOT ((k.key = 'status' AND k.type IN ('text')) OR (k.key = 'said' AND k.type IN ('text'))))));
END;
CREATE TRIGGER ship_pins_refill AFTER UPDATE OF body ON ship_pins WHEN NEW.rest IS NULL AND NEW.body <> '{}' AND json_valid(NEW.body) BEGIN
  DELETE FROM ship_pins WHERE result = NEW.result;
  INSERT INTO ship_pins(result, run, body, at) VALUES (NEW.result, NEW.run, NEW.body, NEW.at);
END;
CREATE TRIGGER ship_pins_bad AFTER UPDATE OF body ON ship_pins WHEN NEW.rest IS NOT NULL AND NOT json_valid(NEW.body) BEGIN
  UPDATE ship_pins SET rest = NULL WHERE result = NEW.result;
END;
CREATE TRIGGER ship_pins_gone AFTER DELETE ON ship_pins BEGIN
  DELETE FROM ship_pin_repos WHERE result = OLD.result;
END;
