d_wait_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.own_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.load1') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.quiet.min_idle_pct') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.quiet.max_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.quiet.idle_pct_first') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.quiet.idle_pct') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.quiet.waited_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.quiet.load1') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.timeout_s') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.pid') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.quiet.readings') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.grace_over.count') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.bisect.lands') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.release_pushes') IN ('true', 'false'), 0) AND NOT coalesce(json_type(rest, '$.progress') IN ('true', 'false'), 0) AND NOT coalesce(json_type(rest, '$.quiet.quiet') IN ('true', 'false'), 0) AND json_type(rest, '$.result') IS NULL AND json_type(rest, '$.item') IS NULL AND json_type(rest, '$.sha') IS NULL AND json_type(rest, '$.status') IS NULL AND json_type(rest, '$.started') IS NULL AND json_type(rest, '$.finished') IS NULL AND json_type(rest, '$.version') IS NULL));
