  UPDATE ships SET rest = json_remove(rest, '$.quiet') WHERE result = NEW.result AND (rest -> '$.quiet' IN ('{}', '[]') OR json_type(rest, '$.quiet') = 'null');
  INSERT INTO ship_lists SELECT NEW.result, 'preflight', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.preflight') e WHERE (json_type(NEW.body, '$.preflight') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.preflight') e WHERE e.type <> 'text'));
  INSERT INTO ship_lists SELECT NEW.result, 'undo', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.undo') e WHERE (json_type(NEW.body, '$.undo') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.undo') e WHERE e.type <> 'text'));
  INSERT INTO ship_lists SELECT NEW.result, 'tail', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.tail') e WHERE (json_type(NEW.body, '$.tail') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.tail') e WHERE e.type <> 'text'));
  INSERT INTO ship_lists SELECT NEW.result, 'bisect_test', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.bisect.tests') e WHERE (json_type(NEW.body, '$.bisect.tests') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.bisect.tests') e WHERE e.type <> 'text'));
  INSERT INTO ship_steps SELECT NEW.result, 'step', e.key, e.value ->> '$.name', e.value ->> '$.log', e.value ->> '$.status', e.value ->> '$.why', e.value ->> '$.timings', e.value ->> '$.profiles[0].audit', e.value ->> '$.profiles[0].bin', e.value ->> '$.profiles[0].fresh', e.value ->> '$.profiles[0].reused', e.value ->> '$.seconds', e.value ->> '$.idle_pct', e.value ->> '$.load1_end', e.value ->> '$.code', NEW.at FROM json_each(NEW.body, '$.steps') e WHERE (json_type(NEW.body, '$.steps') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.steps') e WHERE e.type <> 'object' OR EXISTS (SELECT 1 FROM json_each(e.value) k WHERE k.type <> 'null' AND NOT ((k.key = 'name' AND k.type IN ('text')) OR (k.key = 'log' AND k.type IN ('text')) OR (k.key = 'status' AND k.type IN ('text')) OR (k.key = 'why' AND k.type IN ('text')) OR (k.key = 'timings' AND k.type IN ('text')) OR (k.key = 'profiles' AND k.type = 'array' AND json_array_length(k.value) = 1) OR (k.key = 'seconds' AND k.type IN ('real', 'integer')) OR (k.key = 'idle_pct' AND k.type IN ('real', 'integer')) OR (k.key = 'load1_end' AND k.type IN ('real', 'integer')) OR (k.key = 'code' AND k.type IN ('integer'))))));
  INSERT INTO ship_steps SELECT NEW.result, 'retry', e.key, e.value ->> '$.name', e.value ->> '$.log', e.value ->> '$.status', e.value ->> '$.why', e.value ->> '$.timings', e.value ->> '$.profiles[0].audit', e.value ->> '$.profiles[0].bin', e.value ->> '$.profiles[0].fresh', e.value ->> '$.profiles[0].reused', e.value ->> '$.seconds', e.value ->> '$.idle_pct', e.value ->> '$.load1_end', e.value ->> '$.code', NEW.at FROM json_each(NEW.body, '$.retried') e WHERE (json_type(NEW.body, '$.retried') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.retried') e WHERE e.type <> 'object' OR EXISTS (SELECT 1 FROM json_each(e.value) k WHERE k.type <> 'null' AND NOT ((k.key = 'name' AND k.type IN ('text')) OR (k.key = 'log' AND k.type IN ('text')) OR (k.key = 'status' AND k.type IN ('text')) OR (k.key = 'why' AND k.type IN ('text')) OR (k.key = 'timings' AND k.type IN ('text')) OR (k.key = 'profiles' AND k.type = 'array' AND json_array_length(k.value) = 1) OR (k.key = 'seconds' AND k.type IN ('real', 'integer')) OR (k.key = 'idle_pct' AND k.type IN ('real', 'integer')) OR (k.key = 'load1_end' AND k.type IN ('real', 'integer')) OR (k.key = 'code' AND k.type IN ('integer'))))));
