CREATE TRIGGER ships_refill AFTER UPDATE OF body ON ships WHEN NEW.rest IS NULL AND NEW.body <> '{}' AND json_valid(NEW.body) BEGIN
  DELETE FROM ships WHERE result = NEW.result;
  INSERT INTO ships(result, run, repo, item, sha, status, started, finished, version, body, at) VALUES (NEW.result, NEW.run, NEW.repo, NEW.item, NEW.sha, NEW.status, NEW.started, NEW.finished, NEW.version, NEW.body, NEW.at);
END;
CREATE TRIGGER ships_bad AFTER UPDATE OF body ON ships WHEN NEW.rest IS NOT NULL AND NOT json_valid(NEW.body) BEGIN
  UPDATE ships SET rest = NULL WHERE result = NEW.result;
END;
CREATE TRIGGER ships_gone AFTER DELETE ON ships BEGIN
  DELETE FROM ship_bisect WHERE result = OLD.result;
  DELETE FROM ship_diffcov_faults WHERE result = OLD.result;
  DELETE FROM ship_diffcov_lines WHERE result = OLD.result;
  DELETE FROM ship_grace WHERE result = OLD.result;
  DELETE FROM ship_lists WHERE result = OLD.result;
  DELETE FROM ship_steps WHERE result = OLD.result;
END;
DROP VIEW ships_v2;
CREATE VIEW ships_v2 AS SELECT run, result, repo, item, sha, status, started, finished, version, at,
  CASE WHEN body <> '{}' THEN body ELSE json_set(json_set(json_set(json_patch(json_patch('{}', json_object('result', ships.result, 'item', ships.item, 'sha', ships.sha, 'status', ships.status, 'started', ships.started, 'finished', ships.finished, 'version', ships.version, 'before_clock', CASE WHEN coalesce(ships.before_clock_name, ships.before_clock_status, ships.before_clock_log, ships.before_clock_seconds) IS NOT NULL THEN json_object('name', ships.before_clock_name, 'status', ships.before_clock_status, 'log', ships.before_clock_log, 'seconds', ships.before_clock_seconds) END, 'name', ships.name, 'summary', ships.summary, 'remote', ships.remote, 'branch', ships.branch, 'handoff_sha', ships.handoff_sha, 'base_tag', ships.base_tag, 'release', ships.release, 'install', ships.install, 'loopctl', ships.loopctl, 'failed_step', ships.failed_step, 'bump', ships.bump, 'verdicts', ships.verdicts, 'allow_diffcov', ships.allow_diffcov, 'pid_stamp', ships.pid_stamp, 'grace_over', CASE WHEN coalesce(ships.grace_over_from, ships.grace_canary_sha, ships.grace_why, ships.grace_count, (SELECT 1 FROM ship_grace c WHERE c.result = ships.result LIMIT 1)) IS NOT NULL THEN json_object('over_from', ships.grace_over_from, 'canary_sha', ships.grace_canary_sha, 'why', ships.grace_why, 'count', ships.grace_count, 'repos', json(nullif(nullif((SELECT json_group_object(g.repo, json(g.v)) FROM (SELECT c.repo, json_group_array(c.value ORDER BY c.ord) AS v FROM ship_grace c WHERE c.result = ships.result GROUP BY c.repo) g), '[]'), '{}'))) END, 'bisect', CASE WHEN coalesce(ships.bisect_base, ships.bisect_culprit, ships.bisect_since, ships.bisect_subject, ships.bisect_fault, ships.bisect_lands, (SELECT 1 FROM ship_lists c WHERE c.result = ships.result AND c.kind = 'bisect_test' LIMIT 1), (SELECT 1 FROM ship_bisect c WHERE c.result = ships.result AND c.kind = 'run' LIMIT 1), (SELECT 1 FROM ship_bisect c WHERE c.result = ships.result AND c.kind = 'confirm' LIMIT 1)) IS NOT NULL THEN json_object('base', ships.bisect_base, 'culprit', ships.bisect_culprit, 'since', ships.bisect_since, 'subject', ships.bisect_subject, 'fault', ships.bisect_fault, 'lands', ships.bisect_lands, 'tests', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM ship_lists c WHERE c.result = ships.result AND c.kind = 'bisect_test'), '[]'), '{}')), 'runs', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('sha', c.sha, 'verdict', c.verdict)) ORDER BY c.ord) FROM ship_bisect c WHERE c.result = ships.result AND c.kind = 'run'), '[]'), '{}')), 'confirm', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('sha', c.sha, 'verdict', c.verdict)) ORDER BY c.ord) FROM ship_bisect c WHERE c.result = ships.result AND c.kind = 'confirm'), '[]'), '{}'))) END, 'diffcov_red', CASE WHEN coalesce(ships.diffcov_base, ships.diffcov_said, (SELECT 1 FROM ship_diffcov_lines c WHERE c.result = ships.result LIMIT 1), (SELECT 1 FROM ship_diffcov_faults c WHERE c.result = ships.result LIMIT 1)) IS NOT NULL THEN json_object('base', ships.diffcov_base, 'said', ships.diffcov_said, 'lines', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('file', c.file, 'text', c.text, 'commit', c.commit_sha, 'land', c.land, 'subject', c.subject, 'line', c.line)) ORDER BY c.ord) FROM ship_diffcov_lines c WHERE c.result = ships.result), '[]'), '{}')), 'faults', json(nullif(nullif((SELECT json_group_object(c.fault, c.said) FROM ship_diffcov_faults c WHERE c.result = ships.result), '[]'), '{}'))) END, 'land_wait_s', ships.land_wait_s, 'own_s', ships.own_s, 'load1', ships.load1, 'quiet', CASE WHEN coalesce(ships.quiet_min_idle_pct, ships.quiet_max_s, ships.quiet_idle_pct_first, ships.quiet_idle_pct, ships.quiet_waited_s, ships.quiet_load1, ships.quiet_readings, ships.quiet_ok) IS NOT NULL THEN json_object('min_idle_pct', ships.quiet_min_idle_pct, 'max_s', ships.quiet_max_s, 'idle_pct_first', ships.quiet_idle_pct_first, 'idle_pct', ships.quiet_idle_pct, 'waited_s', ships.quiet_waited_s, 'load1', ships.quiet_load1, 'readings', ships.quiet_readings, 'quiet', CASE ships.quiet_ok WHEN 1 THEN json('true') WHEN 0 THEN json('false') END) END, 'timeout_s', ships.timeout_s, 'pid', ships.pid, 'release_pushes', CASE ships.release_pushes WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'progress', CASE ships.progress WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'preflight', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM ship_lists c WHERE c.result = ships.result AND c.kind = 'preflight'), '[]'), '{}')), 'undo', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM ship_lists c WHERE c.result = ships.result AND c.kind = 'undo'), '[]'), '{}')), 'tail', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM ship_lists c WHERE c.result = ships.result AND c.kind = 'tail'), '[]'), '{}')), 'steps', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('name', c.name, 'log', c.log, 'status', c.status, 'why', c.why, 'timings', c.timings, 'profiles', CASE WHEN c.profile_audit IS NOT NULL THEN json_array(json_object('audit', c.profile_audit, 'bin', c.profile_bin, 'fresh', c.profile_fresh, 'reused', c.profile_reused)) END, 'seconds', c.seconds, 'idle_pct', c.idle_pct, 'load1_end', c.load1_end, 'code', c.code)) ORDER BY c.ord) FROM ship_steps c WHERE c.result = ships.result AND c.kind = 'step'), '[]'), '{}')), 'retried', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('name', c.name, 'log', c.log, 'status', c.status, 'why', c.why, 'timings', c.timings, 'profiles', CASE WHEN c.profile_audit IS NOT NULL THEN json_array(json_object('audit', c.profile_audit, 'bin', c.profile_bin, 'fresh', c.profile_fresh, 'reused', c.profile_reused)) END, 'seconds', c.seconds, 'idle_pct', c.idle_pct, 'load1_end', c.load1_end, 'code', c.code)) ORDER BY c.ord) FROM ship_steps c WHERE c.result = ships.result AND c.kind = 'retry'), '[]'), '{}')), 'consumer_pins', json((SELECT json_patch('{}', json_object('tag', p.tag, 'ruff', p.ruff, 'sweep', p.sweep,
  'committed', CASE WHEN p.sweep IS NOT NULL THEN json((SELECT json_group_array(r.repo ORDER BY r.repo) FROM ship_pin_repos r WHERE r.result = p.result AND r.status = 'committed')) END,
  'not_committed', CASE WHEN p.sweep IS NOT NULL THEN json((SELECT json_group_object(r.repo, r.said) FROM ship_pin_repos r WHERE r.result = p.result AND r.status <> 'committed')) END,
  'pushed', CASE WHEN p.sweep IS NULL THEN json((SELECT json_group_array(r.repo ORDER BY r.repo) FROM ship_pin_repos r WHERE r.result = p.result AND r.status = 'pushed')) END,
  'not_pushed', CASE WHEN p.sweep IS NULL THEN json((SELECT json_group_object(r.repo, r.said) FROM ship_pin_repos r WHERE r.result = p.result AND r.status <> 'pushed')) END))
  FROM ship_pins p WHERE p.result = ships.result)), 'repo', ships.repo, 'quiet_settings', CASE WHEN ships.quiet_max_s IS NOT NULL THEN json_array(ships.quiet_min_idle_pct, ships.quiet_max_s) END)), coalesce(ships.rest, '{}')), '$.item', ships.item), '$.failed_step', ships.failed_step), '$.pid', ships.pid) END AS body FROM ships;
